globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.acceptedAnswers ? {acceptedAnswers: row.acceptedAnswers} : {}),
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(row.textAnswer !== undefined ? {textAnswer: row.textAnswer} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(row.acceptedNumericAnswers ? {acceptedNumericAnswers: row.acceptedNumericAnswers} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + (group.originalNumbers ? group.start : 1)), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.solutionsFile ? {solutionUrl: folder + meta.solutionsFile} : {}),
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

const edition = globalThis.makeSubjectEdition({"subject":"kit","contest":"КИТ","language":"ru","letters":"АБВГД","count":30,"points":3,"year":2010,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"reviewed-8-9.pdf","solutionsFile":"solutions.pdf","reviewedKey":true}, [{"title":"Устройства хранения","question":"Выберите лишнее устройство.","choices":["жёсткий диск","дискета","компакт-диск","дисковод","флэш-память"],"answer":3,"points":3,"steps":["Жёсткий диск, дискета, компакт-диск и флэш-память служат для хранения данных.","Дисковод читает и записывает данные на носитель. После извлечения носителя записанные данные уносят вместе с ним."]},{"title":"Кириллический домен","question":"Первый кириллический домен в сети интернет, запущенный в мае 2010 года, — это…","choices":[".ру",".рф",".ссср",".раша",".россия"],"answer":1,"points":3,"steps":["Сначала уточни, что в вопросе ищут домен, записанный кириллицей и запущенный в мае 2010 года. Латинская запись .ru существовала раньше.","В мае 2010 года заработали первые адреса в кириллической зоне .рф, названной по Российской Федерации."]},{"title":"Устройство джойстика","question":"Джойстик представляет собой…","choices":["устройство вывода, посредством которого можно считывать экранные координаты графического объекта","устройство ввода звуковой информации","устройство ввода информации, посредством которого можно задавать экранные координаты графического объекта","устройство вывода звуковой информации","устройство вывода текстовой информации"],"answer":2,"points":3,"steps":["Наклоняя рычаг джойстика, пользователь передаёт системе направление движения. Данные идут с устройства в компьютер.","Поэтому джойстик служит устройством ввода. Его команды могут задавать положение объекта на экране."]},{"title":"Выравнивание рисунков","question":"Какая из операций Microsoft Word изменяет положение объектов так, как показано на рисунке?","choices":["выровнять по левому краю","распределить по вертикали","выровнять по центру","выровнять по верхнему краю","распределить по горизонтали"],"answer":4,"points":3,"steps":["На втором рисунке объекты сохранили разные высоты. Меняется расстояние слева направо между соседями.","Word равномерно распределил изображения по горизонтали. Операция выравнивания края дала бы общую линию вдоль выбранного края."],"figure":{"src":"assets/kit/2010/8-9-04.webp","alt":"Группы рисунков до операции в Word и после неё."}},{"title":"Буквы на деталях пазла","question":"Приведён алфавит. Что означает слово, составленное из частей пазла?","choices":["имя одного из создателей языка Pascal","наука о способах получения, хранения и использования информации","программа для поиска информации в интернете","операционная система","вычислительная машина, предназначенная для передачи, хранения и обработки информации"],"answer":4,"points":3,"steps":["Сравни каждую деталь с алфавитом. Учитывай отдельно число выступов и выемок сверху, снизу, слева и справа.","Последовательность даёт c, o, m, p, u, t, e, r. Это английское слово computer — компьютер, то есть вычислительная машина."],"figures":[{"src":"assets/kit/2010/8-9-05.webp","alt":"Латинский алфавит, в котором каждой букве соответствует деталь пазла.","caption":"Алфавит"},{"src":"assets/kit/2010/8-9-05-2.webp","alt":"Восемь соединённых деталей пазла.","caption":"Зашифрованное слово"}]},{"title":"Расширение имени файла","question":"Расширение имени файла, как правило, характеризует…","choices":["время создания файла","объём файла","место создания файла","тип данных, хранящихся в файле","место хранения файла"],"answer":3,"points":3,"steps":["Расширение обычно стоит после последней точки. Например, .txt часто относят к тексту, а .jpg к изображению.","С его помощью можно узнать предполагаемый тип данных. Время, размер и папка хранятся как другие сведения о файле."]},{"title":"Порядок трёх событий","question":"Расположите в хронологическом порядке следующие события.","choices":["1, 2, 3","1, 3, 2","2, 3, 1","2, 1, 3","3, 2, 1"],"answer":2,"points":3,"steps":["Электронно-лучевые трубки появились на рубеже XIX и XX веков. Жидкокристаллические экраны начали разрабатывать намного позже, в XX веке.","Windows XP вышла в 2001 году, после обоих изобретений. Хронологический порядок — 2, 3, 1."],"context":"1. Появление Windows XP.\n2. Появление электронно-лучевой трубки.\n3. Появление жидкокристаллического монитора."},{"title":"Графический редактор для Linux","question":"Вася решил перейти на Linux. Помогите ему найти замену Adobe Photoshop.","choices":["OpenOffice","GIMP","Opera","The Bat!","Google"],"answer":1,"points":3,"steps":["Photoshop редактирует растровые изображения. Ищи приложение, которое позволяет открыть снимок, менять пикселы и сохранять картинку.","GIMP выполняет такие задачи и работает в Linux. Остальные варианты предназначены для офиса, веб-страниц, почты или поиска."]},{"title":"Значок файла Excel","question":"Какая из следующих иконок представляет файл Microsoft Excel?","choices":["Значок А","Значок Б","Значок В","Значок Г","Значок Д"],"answer":0,"points":3,"steps":["Ищи схему таблицы с клетками и значок приложения с буквой X. Они видны вместе у рисунка А.","На Б стоит W для Word. Остальные рисунки относятся к папке картинок, браузеру и компьютеру."],"optionFigures":[{"src":"assets/kit/2010/8-9-09-1.webp","alt":"Значок А","width":152,"height":132},{"src":"assets/kit/2010/8-9-09-2.webp","alt":"Значок Б","width":152,"height":132},{"src":"assets/kit/2010/8-9-09-3.webp","alt":"Значок В","width":152,"height":132},{"src":"assets/kit/2010/8-9-09-4.webp","alt":"Значок Г","width":152,"height":132},{"src":"assets/kit/2010/8-9-09-5.webp","alt":"Значок Д","width":152,"height":132}]},{"title":"Двухпалубный корабль","question":"Чип и Дейл играют в игру «Морской бой». Дейл потопил почти все корабли Чипа, кроме одного двухпалубного. Но Чип хитрит, он не нарисовал на своём поле этот корабль. Перед вами лист Дейла. В правом поле он отмечает свои выстрелы и потопленные корабли Чипа. Какое минимальное количество выстрелов необходимо сделать Дейлу, который догадывается о хитрости Чипа, чтобы доказать факт обмана?","choices":["19","18","9","7","5"],"answer":3,"points":3,"steps":["Отбрось на правом поле промахи и клетки, касающиеся потопленных кораблей. Возможны семь непересекающихся двухпалубников: Д5–Е5, Д6–Е6, Д7–Е7, Ж5–Ж6, Ж7–З7, З6–И6, К6–К7. Значит, нужно не меньше семи выстрелов.","Представь оставшиеся клетки на шахматной доске. В любой паре соседей один цвет отличается от другого. Семь клеток одного цвета Д5, Д7, Е6, Ж5, Ж7, З6, К6 пересекают любой возможный двухпалубник."],"figures":[{"src":"assets/kit/2010/8-9-10.webp","alt":"Поле Дейла со своими кораблями.","caption":"Поле Дейла"},{"src":"assets/kit/2010/8-9-10-2.webp","alt":"Поле Чипа с попаданиями и промахами.","caption":"Поле Чипа"}]},{"title":"Чёрный цвет RGB","question":"Чёрному цвету в палитре RGB соответствует…","choices":["255, 255, 255","255, 128, 0","0, 0, 0","128, 255, 255","128, 128, 128"],"answer":2,"points":4,"steps":["Числа RGB задают яркость красного, зелёного и синего света. Например, белый получается при максимальной яркости всех каналов.","Для чёрного каждый источник света выключен. Получается тройка (0, 0, 0)."]},{"title":"Числовой код слова","question":"Для шифровки каждой буквы слова используются двузначные числа. Известно, что буква «к» закодирована числом 15. Среди слов «торт», «ёжик», «станок», «радуга» есть слова, кодируемые последовательностью цифр: 35291815, 303113241115. Какая последовательность цифр является кодом слова «китёнок»?","choices":["151831241115","15181211243515","15183135241115","151831153524","15181135243015"],"answer":2,"points":4,"steps":["Разбей на пары: 35 29 18 15. Последняя пара даёт К. Среди указанных четырёхбуквенных слов на К заканчивается «ёжик», значит, Ё = 35 и И = 18.","Код из шести пар с К на конце относится к слову «станок». Из него Т = 31, Н = 24 и О = 11. «Китёнок» даёт 15 18 31 35 24 11 15."]},{"title":"Совпадение интервалов","question":"Вы — специалист по защите особо важной компьютерной системы от сетевых атак. Только что вражеские хакеры положили ваш сервер, но вы мгновенно восстановили его работоспособность и выяснили, что сервер был обрушен в результате одновременной DDoS-атаки из четырёх вражеских центров. Первый из них атакует ваш сервер с интервалом в 1 час, второй — с интервалом в 2 часа, третий и четвёртый — с интервалами в 3 и 4 часа соответственно. Сколько часов в вашем распоряжении для того, чтобы кардинально решить проблему и не допустить очередного обрушения сервера?","choices":["6","10","12","15","20"],"answer":2,"points":4,"steps":["Отсчитывай от общего события. Следующее совпадение нужно искать на расстоянии, которое делится на 1, 2, 3 и 4 часа.","Число 4 уже делится на 2 и 1. Первое кратное сразу 4 и 3 равно 12, поэтому остаётся 12 часов."]},{"title":"Пропущенное присваивание","question":"Для обмена значений двух переменных был создан алгоритм. Последняя из трёх команд была удалена, остались только две из них. Какая команда была удалена?","choices":["A := A + B","B := A + B","B := B − A","A := A − B","A := B"],"answer":3,"points":4,"steps":["Пусть первоначально A = x и B = y. Первая команда записывает в A сумму x + y. Вторая записывает в B значение (x + y) − y = x.","Чтобы в A получилось y, из текущей суммы x + y надо вычесть новое B, то есть x. Нужна команда A := A − B."],"context":"1. A := A + B\n2. B := A − B\n3. ?"},{"title":"Стрелки на одной прямой","question":"Минутная и часовая стрелки часов в данный момент времени лежат на одной прямой. Следующее расположение стрелок на одной прямой повторится через…","choices":["30 мин","1 час","6 часов","1 час 1 1/11 мин","32 8/11 мин"],"answer":4,"points":4,"steps":["Минутная стрелка проходит 6° за минуту, часовая — 0,5°. Их относительная скорость равна 5,5° в минуту.","Для следующего положения на одной прямой разность углов должна вырасти на 180°. Получаем 180 / 5,5 = 32 8/11 минуты. Этой дроби в бумажном варианте не было, и организаторы засчитали задание всем участникам."],"adaptation":"Вариант Д исправлен по результату расчёта. В исходном конкурсе задание засчитали всем участникам."},{"title":"Открытая архитектура","question":"Открытая архитектура компьютера — это…","choices":["возможность открытого доступа ко всем устройствам компьютера для их ремонта или обслуживания","архитектура компьютера, на которую опубликованы спецификации, техническая документация","возможность открытого доступа к исходному коду любого программного обеспечения, поставляемого с компьютером","возможность открытия любого программного обеспечения на компьютере с данной архитектурой","возможность открытия любой части компьютера в течение гарантийного срока"],"answer":1,"points":4,"steps":["Архитектура описывает, из каких частей собран компьютер и как они взаимодействуют. Чтобы независимый изготовитель мог выпустить совместимую часть, ему нужны правила соединения и обмена данными.","У открытой архитектуры эти спецификации опубликованы. Речь идёт о доступности технической документации."]},{"title":"Две игры за победу","question":"В компьютерном клубе даётся две призовые игры, если игра завершилась победой геймера. Геймер Вася заплатил за 5 игр и сыграл 25 игр, использовав все призовые игры. Вася одержал…","choices":["5 побед","10 побед","15 побед","20 побед","25 побед"],"answer":1,"points":4,"steps":["Из 25 игр оплачены только 5. Значит, 25 − 5 = 20 игр достались как призы.","За каждую победу начисляют две игры. Двадцать призовых игр получаются за 20 / 2 = 10 побед."],"adaptation":"Уточнено, что Вася использовал все полученные призовые игры."},{"title":"Эмблема системы","question":"Логотип какой операционной системы представлен на рисунке?","choices":["Windows","FreeBSD","MacOS","Linux","Solaris"],"answer":3,"points":4,"steps":["На картинке пингвин Tux. Он служит известным символом одного семейства операционных систем.","Tux связан с Linux. У Windows, FreeBSD и других вариантов свои символы."],"figure":{"src":"assets/kit/2010/8-9-18.webp","alt":"Эмблема операционной системы."}},{"title":"Процессоры одной частоты","question":"Организация имеет семь компьютеров. Оказалось, что для любого из них найдутся три других с той же частотой процессора. У какого наибольшего числа компьютеров по условию обязательно одинаковая частота процессора?","choices":["у 3 компьютеров","у 4 компьютеров","у 5 компьютеров","у 6 компьютеров","у 7 компьютеров"],"answer":4,"points":4,"steps":["Собери компьютеры в группы по частоте. По условию у каждого компьютера есть ещё три с той же частотой, так что каждая группа имеет не меньше четырёх участников.","Две такие группы потребовали бы хотя бы восемь компьютеров. Есть только семь, поэтому процессоры всех семи имеют одинаковую частоту."],"adaptation":"Уточнено, что ищем наибольшее гарантированное число компьютеров с одной частотой."},{"title":"Маршруты по уровням игры","question":"Геймер Вася играет в игру, в которой 6 уровней. После того, как игрок минует последний уровень, игра заканчивается. При этом на каждом из первых пяти уровней существует ключ, воспользовавшись которым, можно перепрыгнуть вперёд через один уровень. Ключ актуален только для того уровня, на котором он обнаружен. Какое количество различных вариантов пройти игру есть у Васи?","choices":["6","7","8","9","13"],"answer":4,"points":4,"steps":["Обозначь конец игры как позицию 7. Из каждой доступной позиции игрок переходит на одну или две позиции вперёд.","В каждую следующую позицию можно попасть из двух предыдущих. Посчитай числа путей от старта: 1, 1, 2, 3, 5, 8, 13. Для конца игры имеется 13 путей."]},{"title":"Цифры вместо букв","question":"В одной фирме сломалась клавиатура компьютера. Вместо букв «б», «в», «л», «о», «т» печатаются некоторые цифры. Разным буквам соответствуют разные цифры. Сумма цифр слова «бот» равна 8, «вол» — 9, «болт» — 11, «ото» — 9. В этой кодировке букве «т» может соответствовать цифра…","choices":["1","2","3","4","5"],"answer":4,"points":5,"steps":["Вычти сумму «бот» из «болт»: Л = 3. Из «ото» следует 2О + Т = 9, поэтому Т нечётная.","При Т = 1 получаются О = 4 и Б = 3, совпадающая с Л. При Т = 3 имеем О = 3, тоже совпадение. При Т = 5 получаются О = 2, В = 4, Б = 1. Все цифры различны, подходит 5."]},{"title":"Правило числового ряда","question":"Продолжите последовательность: 3, 8, 25, 78, …","choices":["92","115","183","239","287"],"answer":3,"points":5,"steps":["Умножь каждое число на 3 и сравни с последующим. В первый раз нужно вычесть 1, во второй прибавить 1, в третий прибавить 3.","Поправка каждый раз увеличивается на 2. Следующая поправка равна 5, и новое число будет 78 · 3 + 5 = 239."]},{"title":"Размер строки Unicode","question":"В отрывке «Расстояние от Солнца до Земли равно 150000000 км.» каждый символ кодируется двухбайтным словом. Объём этого предложения в кодировке Unicode равен…","choices":["49 бит","784 бита","49 байт","784 байта","98 бит"],"answer":1,"points":5,"steps":["Сосчитай буквы, пробелы, девять цифр и точку. В предложении 49 символов.","По условию каждый символ занимает 2 байта, то есть 16 бит. Объём равен 49 · 16 = 784 бита."]},{"title":"Условия о днях недели","question":"Если этот день не идёт вслед за вторником и не перед пятницей, а завтра не понедельник и вчера был не понедельник, а послезавтра будет не воскресенье и позавчера был не четверг, то что это за день?","choices":["понедельник","вторник","среда","четверг","суббота"],"answer":0,"points":5,"steps":["Не после вторника — исключаем среду. Не перед пятницей — исключаем четверг. Завтра не понедельник, вчера не понедельник — исключаем воскресенье и вторник.","Послезавтра не воскресенье и позавчера не четверг — исключаем пятницу и субботу. Остаётся понедельник."]},{"title":"Цифра в длинной записи","question":"Петя решил выписать все натуральные числа, начиная с единицы, друг за другом. Но сумел добраться только до 3210-й цифры, после чего уснул. Последней цифрой, которую написал Петя, была цифра…","choices":["1","2","3","4","5"],"answer":0,"points":5,"steps":["До 999 включительно идут 9 однозначных, 90 двузначных и 900 трёхзначных чисел. Они занимают 9 + 180 + 2700 = 2889 цифр.","Остаётся 321 цифра, значит, 80 полных четырёхзначных чисел (1000–1079) и первая цифра 1080. Это 1."]},{"title":"Цикл формул в таблице","question":"Дан фрагмент электронной таблицы. После выполнения вычислений без итераций значение в ячейке D2 будет равно…","choices":["8","6","3","4","формула неразрешима"],"answer":4,"points":5,"steps":["Чтобы вычислить D2, формула требует B2. Для B2 уже нужна A2.","Но формула A2 использует D2, откуда начали вычисление. Получилась циклическая ссылка A2 → D2 → B2 → A2. Обычный расчёт таблицы останавливается."],"context":"Строка 1: A1 = 3, B1 = 0, C1 = 4, D1 = 5.\nСтрока 2: A2 содержит =C1−A1+D2, B2 содержит =A1*2−A2*4, C2 содержит =B2/2, D2 содержит =B2+C1.","adaptation":"Формулы вычисляются с обычными настройками таблицы, без итераций."},{"title":"Каркас куба из проволоки","question":"Дана проволока конечной длины, из которой необходимо изготовить каркас куба. Для этого её можно гнуть, разрезать и паять. При одном разрезе проволока разделяется на две части. Вдоль каждого ребра куба проволока должна проходить ровно один раз. Минимальное количество разрезов для изготовления каркаса равно…","choices":["1","2","3","4","6"],"answer":2,"points":5,"steps":["В каждой вершине куба сходятся три ребра. Проходящий через вершину кусок проволоки занимает пару рёбер, значит, в каждой вершине должен быть конец какого-то куска. Восемь концов требуют хотя бы четырёх кусков.","Один длинный кусок проведи по трём рёбрам нижней грани, затем по вертикали, затем по четырём рёбрам верхней грани. На три оставшихся вертикальных ребра и одно нижнее нужны ещё четыре отдельные части, но два смежных из них можно согнуть одним куском. В итоге достаточны четыре куска, то есть три разреза."]},{"title":"Старинная цена фуро","question":"Старинная задача звучит так. Если учесть, что «вполчетверта» означает «в три с половиной раза», алтын — это 3 копейки, то стоимость фуро составляет…","choices":["7/3 копейки","3 копейки","7 копеек","21/4 копейки","27/4 копейки"],"answer":3,"points":5,"steps":["Четыре с половиной алтына — это 4,5 · 3 = 13,5 копейки. По условию это вдвое больше суммарной цены фуро и чепца.","Сумма цен равна 6,75 копейки. Фуро в 3,5 раза дороже чепца, всего 4,5 доли цены чепца. Одна доля равна 1,5 копейки, фуро стоит 1,5 · 3,5 = 5,25 = 21/4 копейки."],"context":"Нововъезжей в Россию иностранной мадаме\nВздумалось оценить свое богатство в чемодане:\nНовой выдумки нарядное фуро\nИ праздничный чепец а ля фигаро.\nОценщик был русак,\nСказал мадаме так:\n«Богатства твоего первая вещь фуро\nВполчетверта дороже чепца фигаро;\nВообще же стоят те с половиною четыре алтына,\nА настоящая им цена только сего половина».\nСпрашивается каждой вещи цена,\nС чем иностранка к россам привезена."},{"title":"Ошибка сортировки вставками","question":"Петя написал программу, которая должна выполнять сортировку массива x[0…n] по возрастанию: очередное входное данное вставляется на нужную позицию в уже отсортированном списке. Ошибка содержится в строке…","choices":["1","8","3","9","5"],"answer":2,"points":5,"steps":["При вставке число t сравнивают с уже упорядоченной частью. Она расположена слева от позиции i. Большие элементы нужно передвигать вправо, начиная с ближайшего к t.","Поэтому j должно идти от i к 1, а в строке 3 идёт от 1 к i. При проходе слева направо можно остановиться у маленького элемента слишком рано."],"context":"1. НЦ ДЛЯ i ОТ 1 ДО n\n2.   t := x[i]\n3.   НЦ ДЛЯ j ОТ 1 ДО i\n4.     k := j\n5.     ЕСЛИ x[j−1] ≤ t\n6.       ТО ПРЕРВАТЬ ЦИКЛ\n7.     ВСЕ\n8.     x[j] := x[j−1]\n9.     k := j−1\n10.  КЦ\n11.  x[k] := t\n12. КЦ"},{"title":"Целые точки внутри эллипса","question":"Для нахождения количества целочисленных точек, лежащих внутри эллипса x²/9 + y²/4 = 1, составлена программа, фрагмент которой приведён ниже. Чему равно значение SUM, то есть сколько целочисленных точек лежит внутри эллипса?","choices":["3","5","9","15","21"],"answer":3,"points":5,"steps":["Для целых ординат возможны только −1, 0 и 1. При y = ±2 точка уже на границе или снаружи.","На каждой из трёх строк подходят x = −2, −1, 0, 1, 2: даже в крайнем случае 4/9 + 1/4 < 1. Получаем 3 · 5 = 15 точек."],"context":"SUM := 0\nНЦ ДЛЯ I ОТ −2 ДО 2\n  НЦ ДЛЯ J ОТ −3 ДО 3\n    ЕСЛИ I*I/9 + J*J/4 < 1 ТО\n      SUM := SUM + 1\n    ВСЕ\n  КЦ\nКЦ","figure":{"src":"assets/kit/2010/8-9-30.webp","alt":"Эллипс с отмеченными полуосями a и b."}}]);
